from typing import Final

import pytest

# Built-in defaults, in the order they appear in the result.
DEFAULTS: Final[dict[str, str]] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] -> values[i] onto DEFAULTS and return the resulting values.

    The result lists the value for "mode" first, then "level", then the values
    of any other keys in the order they first appear in ``keys``. A repeated
    key takes its last given value.

    Raises ValueError if ``keys`` and ``values`` have different lengths.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")

    # Dict assignment keeps the position of a key's first insertion while
    # updating its value, so repeated keys take the last value and extra keys
    # keep first-appearance order.
    merged: dict[str, str] = {}
    for key, value in zip(keys, values, strict=True):
        merged[key] = value

    mode = merged.get("mode", DEFAULTS["mode"])
    level = merged.get("level", DEFAULTS["level"])
    extras = [v for k, v in merged.items() if k not in DEFAULTS]
    return [mode, level, *extras]


def test_no_overrides_returns_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_builtin_level() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_override_builtin_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_extra_key_appended_after_defaults() -> None:
    assert settings(["color"], ["red"]) == ["fast", "3", "red"]


def test_builtin_keys_first_regardless_of_input_order() -> None:
    assert settings(["color", "mode"], ["red", "slow"]) == ["slow", "3", "red"]


def test_extra_keys_keep_given_order() -> None:
    assert settings(["b", "a"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_repeated_key_uses_last_value() -> None:
    assert settings(["x", "x"], ["1", "2"]) == ["fast", "3", "2"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["mode", "level"], ["slow"])
